const results = await Promise.allSettled([
  tools.exec_command({cmd:"ls -la","workdir":"/work","yield_time_ms":10000}),
  tools.exec_command({cmd:"rg --files -g '!node_modules' -g '!vendor' -g '!dist' -g '!build' -g '!coverage' | head -150","workdir":"/work","yield_time_ms":10000}),
  tools.exec_command({cmd:"find /work -name AGENTS.md -print","workdir":"/work","yield_time_ms":10000})
]); for (const r of results) text(r.status === "fulfilled" ? r.value.output : String(r.reason));

const results = await Promise.allSettled([
  tools.exec_command({cmd:"cat README.md","workdir":"/work","yield_time_ms":10000}),
  tools.exec_command({cmd:"cat package.json","workdir":"/work","yield_time_ms":10000}),
  tools.exec_command({cmd:"rg -n -i 'beep|audio|sound|oscillator|frequency|tone|match|pair' src tests scripts | head -200","workdir":"/work","yield_time_ms":10000}),
  tools.exec_command({cmd:"git status --short","workdir":"/work","yield_time_ms":10000})
]); for (const r of results) text(r.status === "fulfilled" ? r.value.output : String(r.reason));

